changeSet.sql:
CREATE TABLE question_votes (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    question_id  UUID NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
    user_id      UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    weight       SMALLINT NOT NULL,
    voted_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT question_votes_weight_check CHECK (weight IN (-1, 1)),
    CONSTRAINT question_votes_unique UNIQUE (question_id, user_id)
);

CREATE INDEX idx_question_votes_question ON question_votes(question_id);
CREATE INDEX idx_question_votes_user ON question_votes(user_id);

rollback.sql:
DROP INDEX IF EXISTS idx_question_votes_user;
DROP INDEX IF EXISTS idx_question_votes_question;
DROP TABLE IF EXISTS question_votes;
